<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script>
const filterForm=document.querySelector('.filters'),resetFilter=document.querySelector('.filters .secondary'),favoriteKey='ozman_real_estate_favorites',compareKey='ozman_real_estate_compare_{{ $company?->id ?? 'global' }}';
let propertyMap=null,propertyBounds=[],marketView='list',filterController=null,filterTimer=null;
const readIds=key=>{try{return JSON.parse(localStorage.getItem(key)||'[]').map(Number)}catch{return[]}};
const saveIds=(key,ids)=>localStorage.setItem(key,JSON.stringify([...new Set(ids)]));
function refreshFavorites(){const ids=readIds(favoriteKey);document.querySelectorAll('[data-favorite]').forEach(button=>{const active=ids.includes(Number(button.dataset.favorite));button.classList.toggle('active',active);button.textContent=active?'♥':'♡'})}
function refreshCompare(){const ids=readIds(compareKey).slice(0,4);document.querySelectorAll('[data-compare]').forEach(input=>input.checked=ids.includes(Number(input.value)));document.getElementById('compare-count').textContent=ids.length;document.getElementById('compare-link').href='{{ route('real-estate.compare') }}?ids='+ids.join(',');document.getElementById('compare-bar').classList.toggle('show',ids.length>1)}
function bindCardActions(){document.querySelectorAll('[data-favorite]:not([data-ajax-bound])').forEach(button=>{button.dataset.ajaxBound='1';button.addEventListener('click',()=>{let ids=readIds(favoriteKey),id=Number(button.dataset.favorite);ids=ids.includes(id)?ids.filter(value=>value!==id):[...ids,id];saveIds(favoriteKey,ids);refreshFavorites()})});document.querySelectorAll('[data-compare]:not([data-ajax-bound])').forEach(input=>{input.dataset.ajaxBound='1';input.addEventListener('change',()=>{let ids=readIds(compareKey),id=Number(input.value);if(input.checked&&!ids.includes(id)&&ids.length<4)ids.push(id);if(!input.checked)ids=ids.filter(value=>value!==id);saveIds(compareKey,ids);refreshCompare()})});refreshFavorites();refreshCompare()}
function readMapItems(){try{return JSON.parse(document.getElementById('market-map-data')?.textContent||'[]')}catch{return[]}}
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[character]));
function initializeMap(){if(propertyMap){propertyMap.remove();propertyMap=null}propertyBounds=[];const element=document.getElementById('property-map'),items=readMapItems();if(!window.L||!element||!items.length)return;propertyMap=L.map(element);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(propertyMap);items.forEach(property=>{propertyBounds.push([property.lat,property.lng]);L.marker([property.lat,property.lng]).addTo(propertyMap).bindPopup(`<div class="map-popup"><a href="${escapeHtml(property.url)}">${escapeHtml(property.title)}</a><br>${Number(property.price).toLocaleString()} ${escapeHtml(property.currency)}</div>`)});propertyMap.fitBounds(propertyBounds,{padding:[30,30],maxZoom:15})}
function setMarketView(view){marketView=view==='map'&&document.getElementById('property-map')?'map':'list';const showMap=marketView==='map',layout=document.getElementById('market-layout'),mapToggle=document.getElementById('map-toggle'),listToggle=document.getElementById('list-toggle');layout?.classList.toggle('map-mode',showMap);layout?.classList.toggle('no-map',!showMap);mapToggle?.classList.toggle('active',showMap);listToggle?.classList.toggle('active',!showMap);mapToggle?.setAttribute('aria-pressed',String(showMap));listToggle?.setAttribute('aria-pressed',String(!showMap));if(showMap&&propertyMap)setTimeout(()=>{propertyMap.invalidateSize();if(propertyBounds.length)propertyMap.fitBounds(propertyBounds,{padding:[30,30],maxZoom:15})},50)}
function bindResultControls(){document.getElementById('map-toggle')?.addEventListener('click',()=>setMarketView('map'));document.getElementById('list-toggle')?.addEventListener('click',()=>setMarketView('list'));document.getElementById('market-sort')?.addEventListener('change',event=>{const url=formUrl();event.target.value?url.searchParams.set('sort',event.target.value):url.searchParams.delete('sort');url.searchParams.delete('page');loadMarket(url)});bindCardActions();initializeMap();setMarketView(marketView)}
function syncAlertFilters(){const alertForm=document.querySelector('.alert-form');if(!alertForm)return;alertForm.querySelectorAll('input[data-filter-copy]').forEach(input=>input.remove());for(const [key,value] of new URLSearchParams(new FormData(filterForm))){if(!value)continue;const input=document.createElement('input');input.type='hidden';input.name=`filters[${key}]`;input.value=value;input.dataset.filterCopy='1';alertForm.prepend(input)}}
function formUrl(){const url=new URL(filterForm.action||location.href,location.href),parameters=new URLSearchParams(new FormData(filterForm));parameters.delete('page');for(const [key,value] of [...parameters])if(value==='')parameters.delete(key);url.search=parameters.toString();return url}
function syncFormFromUrl(url){const parameters=url.searchParams;filterForm.querySelectorAll('[name]').forEach(field=>{if(field.type==='radio'){field.checked=(parameters.get(field.name)||'')===(field.value||'')}else if(field.type==='checkbox'){field.checked=parameters.has(field.name)}else{field.value=parameters.get(field.name)||''}});const sort=document.getElementById('market-sort');if(sort)sort.value=parameters.get('sort')||''}
function clearFilterForm(){filterForm.querySelectorAll('[name]').forEach(field=>{if(field.type==='radio')field.checked=field.value==='';else if(field.type==='checkbox')field.checked=false;else if(field.tagName==='SELECT')field.selectedIndex=0;else field.value=''})}
async function loadMarket(target,{history=true,scroll=false,syncForm=false}={}){const url=target instanceof URL?target:new URL(target,location.href),results=document.getElementById('market-results');filterController?.abort();const controller=new AbortController();filterController=controller;if(syncForm)syncFormFromUrl(url);results?.classList.add('ajax-loading');results?.setAttribute('aria-busy','true');filterForm.classList.add('ajax-loading');try{const response=await fetch(url,{headers:{'X-Requested-With':'XMLHttpRequest','Accept':'text/html'},signal:controller.signal});if(!response.ok)throw new Error(`HTTP ${response.status}`);const documentCopy=new DOMParser().parseFromString(await response.text(),'text/html'),fresh=documentCopy.getElementById('market-results');if(!fresh)throw new Error('Missing market results');propertyMap?.remove();propertyMap=null;results.replaceWith(fresh);if(history)window.history.pushState({},'',url);syncAlertFilters();bindResultControls();if(scroll)document.getElementById('market-results')?.scrollIntoView({behavior:'smooth',block:'start'})}catch(error){if(error.name!=='AbortError'){console.error(error);results?.classList.remove('ajax-loading');results?.removeAttribute('aria-busy');alert('تعذر تحديث النتائج. تحقق من الاتصال وحاول مرة أخرى.')}}finally{if(filterController===controller){filterForm.classList.remove('ajax-loading');filterController=null}}}
function scheduleFilter(delay=250){clearTimeout(filterTimer);filterTimer=setTimeout(()=>loadMarket(formUrl()),delay)}
filterForm.addEventListener('submit',event=>{event.preventDefault();scheduleFilter(0)});
filterForm.addEventListener('change',event=>{if(event.target.matches('select,input[type="radio"],input[type="checkbox"]'))scheduleFilter(0);else if(event.target.matches('input[type="number"]'))scheduleFilter(350)});
filterForm.querySelectorAll('input[type="text"],input:not([type])').forEach(input=>input.addEventListener('input',()=>scheduleFilter(450)));
resetFilter?.addEventListener('click',event=>{event.preventDefault();clearTimeout(filterTimer);clearFilterForm();loadMarket(new URL(resetFilter.href),{history:true})});
document.addEventListener('click',event=>{const link=event.target.closest('#market-results .pagination a');if(!link)return;event.preventDefault();loadMarket(new URL(link.href),{scroll:true})});
window.addEventListener('popstate',()=>loadMarket(new URL(location.href),{history:false,syncForm:true}));
const channel=document.getElementById('alert-channel'),contact=document.getElementById('alert-contact');channel.onchange=()=>{contact.type=channel.value==='email'?'email':'tel';contact.name=channel.value==='email'?'email':'phone';contact.placeholder=channel.value==='email'?'{{ $labels['email'] }}':'{{ $labels['whatsapp'] }}'};
bindResultControls();syncAlertFilters();
</script>
</body></html>
